import javax.swing.*; import java.awt.*; import java.util.*;
public class AppointmentDesk extends JFrame {
 private final JTextField patient=new JTextField(12); private final JComboBox<String> dept=new JComboBox<>(new String[]{"Cardiology","Dermatology","Orthopedics"});
 private final JComboBox<String> doctor=new JComboBox<>(), slot=new JComboBox<>(new String[]{"09:00","10:00","11:00"}); private boolean booking=false;
 private final Map<String,java.util.List<String>> doctors=Map.of("Cardiology",java.util.List.of("Dr Rao","Dr Iyer"),"Dermatology",java.util.List.of("Dr Shah"),"Orthopedics",java.util.List.of("Dr Kumar","Dr Das"));
 public AppointmentDesk(){super("Outpatient Appointment Desk"); setLayout(new GridLayout(0,2,6,6)); add(new JLabel("Patient ID"));add(patient);add(new JLabel("Department"));add(dept);add(new JLabel("Doctor"));add(doctor);add(new JLabel("Time slot"));add(slot); JButton book=new JButton("Book");add(book);add(new JLabel("")); dept.addActionListener(e->refreshDoctors()); book.addActionListener(e->book()); addWindowListener(new java.awt.event.WindowAdapter(){public void windowClosing(java.awt.event.WindowEvent e){if(booking&&JOptionPane.showConfirmDialog(AppointmentDesk.this,"A booking is in progress. Close?","Confirm",JOptionPane.YES_NO_OPTION)!=JOptionPane.YES_OPTION)setDefaultCloseOperation(DO_NOTHING_ON_CLOSE);else setDefaultCloseOperation(DISPOSE_ON_CLOSE);}}); setDefaultCloseOperation(DO_NOTHING_ON_CLOSE);pack();refreshDoctors();setLocationRelativeTo(null); }
 private void refreshDoctors(){doctor.removeAllItems(); for(String d:doctors.getOrDefault((String)dept.getSelectedItem(),java.util.List.of()))doctor.addItem(d);}
  private void book(){if(patient.getText().trim().isEmpty()||doctor.getSelectedItem()==null){JOptionPane.showMessageDialog(this,"Patient ID and doctor are required.","Validation",JOptionPane.ERROR_MESSAGE);return;} booking=true; SwingWorker<Void,Void> worker=new SwingWorker<>(){protected Void doInBackground(){return null;} protected void done(){booking=false;JOptionPane.showMessageDialog(AppointmentDesk.this,"Appointment booked for "+patient.getText()+" with "+doctor.getSelectedItem()+" at "+slot.getSelectedItem());}};worker.execute();}
 public static void main(String[]x){SwingUtilities.invokeLater(()->new AppointmentDesk().setVisible(true));}
}
